"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7453],{63606:e=>{e.exports=JSON.parse('{"functions":[{"name":"Create","desc":"Create a container and the inventory behind it.","params":[{"name":"config","desc":"","lua_type":"ContainerConfig?"},{"name":"options","desc":"","lua_type":"CreateOptions?"}],"returns":[{"desc":"","lua_type":"ContainerData\\n"}],"function_type":"method","source":{"line":274,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Get","desc":"","params":[{"name":"id","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"ContainerData?\\n"}],"function_type":"method","source":{"line":336,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"GetAll","desc":"Every live container. Copied out, so removal during iteration is safe.","params":[],"returns":[{"desc":"","lua_type":"{ ContainerData }\\n"}],"function_type":"method","source":{"line":345,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Remove","desc":"Tear a container down, handing back whatever it still held.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"{ ItemStack }\\n"}],"function_type":"method","source":{"line":358,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Clear","desc":"Drop every container. Used by tests and by a place teardown.","params":[],"returns":[],"function_type":"method","source":{"line":371,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"SetModified","desc":"Mark the container as needing a respawn.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[],"function_type":"method","source":{"line":385,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"ToggleEnabled","desc":"","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"enabled","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"method","source":{"line":395,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"HasSearched","desc":"Whether a given player has searched this container since its last respawn.\\n\\nKeyed on UserId, matching the OwnerId every other service already uses.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":407,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"GetCFrame","desc":"The container\'s current placement.\\n\\nA movable container (vehicle storage) reads its object\'s pivot, because its\\nstored CFrame went stale the moment it drove away.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"CFrame\\n"}],"function_type":"method","source":{"line":442,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"IsInRange","desc":"Whether `player` is close enough to interact.\\n\\nReads the character fresh, per the no-session-object convention.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":460,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Unlock","desc":"","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":476,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"DamageLock","desc":"Damage the lock. Returns true only on the hit that breaks it.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"damage","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":495,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"SpawnItems","desc":"Fill the container from its spawn data.\\n\\nReturns whether anything was placed. Delegates to `SpawnProvider`; see the\\nheader for why.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":531,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"DespawnItems","desc":"Empty the container.\\n\\nReturns the stacks that were in it. The old version destroyed each spawned\\nitem in place; a stack owns no identity, so dropping the reference is what\\ndestruction means here -- and handing them back lets a caller relocate them\\ninstead.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"{ ItemStack }\\n"}],"function_type":"method","source":{"line":578,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Take","desc":"Move quantity out of one of the container\'s slots into `destination`.\\n\\nReturns what actually moved. The old signature returned\\n`(took_anything, remaining)` and recomputed the remainder from three\\nseparate quantities at the call site; `TransferResult` carries both, named.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"destination","desc":"","lua_type":"Inventory"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":601,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"TakeFor","desc":"`Take`, gated on range and on the container being open to that player.\\n\\nThe gate lives here because it is the authority check: a client asking to\\ntake something is not trusted about where it is standing, nor about whether\\nit ever opened the container.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"player","desc":"","lua_type":"Player"},{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"destination","desc":"","lua_type":"Inventory"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":637,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Deposit","desc":"Put quantity from `holder` into the container.\\n\\nThe mirror of `Take`, and the reason a drop pile works: a container is just\\nan inventory, so depositing is the same transfer in the other direction.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":663,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"CollectInventories","desc":"Every inventory a viewer of this container should be able to see.\\n\\nFor an `Inventory` container that is just its own. For an `ItemGroup` it is\\nits own plus the inventory nested inside each slot -- a pile of backpacks\\nshows the backpacks\' contents, not the backpacks.\\n\\nThe old version did this walk inline in `OpenContainer`, and again in a\\nslot-change handler, and again in `CloseContainer` to undo it. Nesting is\\ntracked by holder id now, so it is one function with one caller per event.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"{ Inventory }\\n"}],"function_type":"method","source":{"line":696,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Open","desc":"Open the container for a player.\\n\\nReturns the inventories to expose, or nil when the open was refused --\\ndisabled, locked, or out of range. Note what it does NOT do: attach anything\\nto the player. `OnContainerOpened` plus this return value is the whole\\nprotocol, so the replication layer decides what reaches the client.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"{ Inventory }?\\n"}],"function_type":"method","source":{"line":723,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"Close","desc":"Close the container for a player.\\n\\nSafe to call for a player that never had it open -- the old version had to\\nrun its listener cleanup in that case anyway, because a vanished client left\\nconnections behind. There are no per-viewer connections now, so there is\\nnothing to leak.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"{ Inventory }\\n"}],"function_type":"method","source":{"line":757,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"IsOpen","desc":"Whether anyone has it open.","params":[{"name":"container","desc":"","lua_type":"ContainerData"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":778,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}},{"name":"CloseAll","desc":"Close for every viewer. Used when a container is disabled or destroyed.","params":[{"name":"container","desc":"","lua_type":"ContainerData"},{"name":"players","desc":"","lua_type":"{ Player }"}],"returns":[],"function_type":"method","source":{"line":787,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}}],"properties":[],"types":[],"name":"ContainerService","desc":"World containers: crates, lockers, vehicle storage, loot piles.\\n\\nWHAT CHANGED\\n\\nA container\'s contents were a bespoke `InventoryController` reached through\\n`container.Inventory`, and opening one reached all the way into\\n`client.Manager.AccessibleInventoryManager` to attach it -- so the service\\nthat owns crates also owned a piece of the replication protocol, and could\\nnot be exercised without a live client session.\\n\\nHere a container\'s contents are an ordinary `Inventory` of kind `Container`,\\nand `Open` RETURNS the inventories to expose rather than attaching them. Who\\nreceives them is the replication layer\'s business. That inversion is what\\nlets open/close/search/lock be tested with no player, no network and no\\nplace.\\n\\n`ItemGroup` containers -- the ones whose slots hold items that are themselves\\ncontainers, like a pile of backpacks -- were the messiest part of that\\ncoupling: opening one walked every slot, found each item\'s nested\\ninventories, and attached them individually with `Silent` metadata, then\\nre-ran the same walk on every slot change. `InventoryService` already tracks\\nnesting by holder id, so that walk is `CollectInventories` and the change\\nhandling is one signal.\\n\\nWHAT IS DELEGATED\\n\\nLoot spawning still belongs to `ItemSpawnDataService`, which is not ported.\\n`SpawnProvider` is the seam it will plug into; until then `SpawnItems`\\nreports that it spawned nothing, which is exactly what an unconfigured\\ncontainer should do. Sounds and attribute writes live in the binding.","source":{"line":37,"path":"src2/server/EmberServerLibrary/GameServer/Services/ContainerService.service.luau"}}')}}]);